public static class IronCondorPositionCommandHandlers{public static ServiceResult<GuidResult>Execute(this OpenIronCondorPositionCommand c,IronCondorPositionCommandState s)=>Apply(c,s,m=>m.Open(c.Trade,c.EntityId.PositionId,c.EffectiveAtUtc));public static ServiceResult<GuidResult>Execute(this UpdateIronCondorPositionLegMarketPriceCommand c,IronCondorPositionCommandState s)=>Apply(c,s,m=>m.UpdateLeg(c.TradeLegId,c.Price,c.SourceSequence,c.EffectiveAtUtc,c.RouteGeneration));public static ServiceResult<GuidResult>Execute(this EndOfDayIronCondorPositionCommand c,IronCondorPositionCommandState s)=>Apply(c,s,m=>m.EndOfDay(c.EffectiveAtUtc));public static ServiceResult<GuidResult>Execute(this CloseIronCondorPositionCommand c,IronCondorPositionCommandState s)=>Apply(c,s,m=>m.Close(c.EffectiveAtUtc));public static ServiceResult<GuidResult>Execute(this CorrectIronCondorPositionBasisCommand c,IronCondorPositionCommandState s)=>Apply(c,s,m=>m.CorrectBasis(c.TradeLegId,c.Price,c.EffectiveAtUtc));public static ServiceResult<GuidResult>Execute(this SnapshotIronCondorPositionCommand c,IronCondorPositionCommandState s)=>s.Current is{}x?TradeCommandResult.Accepted(c.CommandId):new ServiceFailed<GuidResult>(c.ErrorCode,"POSITION.NOT_FOUND");static ServiceResult<GuidResult>Apply(PositionCommand c,IronCondorPositionCommandState s,Func<StrategyPositionActorStateMachine,TradeDecision<StrategyPositionSnapshot>>f){var m=new StrategyPositionActorStateMachine();if(s.Current is{}x)m.Replay(x);var d=f(m);if(!d.Accepted||d.Value is null)return TradeCommandResult.Rejected(c.ErrorCode,d);s.Update(new IronCondorPositionChangedEvent{EntityId=c.EntityId,State=d.Value},c);return TradeCommandResult.Accepted(c.CommandId);}}
